// V11.18 — Recor foot visuals are embedded once in the client bundle.
// This removes any dependency on static asset routing/cache when the configurator
// and the client dossier are rendered.
const RECOR_FOOT_VISUALS={
  ASTER:"data:image/jpeg;base64,",
  BALL_CLAW:"data:image/jpeg;base64,",
  WOOD:"data:image/jpeg;base64,",
  IMPERIAL:"data:image/jpeg;base64,",
  LION:"data:image/jpeg;base64,",
  PEDESTAL:"data:image/jpeg;base64,",
  PRINCESS:"data:image/jpeg;base64,",
  CARLTON:"data:image/jpeg;base64,"
};
function recorEmbeddedVisual(item){
  if(!item || item.manufacturer!=="Recor")return "";
  if(!["Pieds Recor","Socles Recor"].includes(String(item.collection||"")))return "";
  const t=normalizeText(`${item.collection||""} ${item.base||""} ${item.reference||""} ${item.designation||""}`);
  if(/aster/.test(t))return RECOR_FOOT_VISUALS.ASTER;
  if(/ball.*claw|claw.*ball/.test(t))return RECOR_FOOT_VISUALS.BALL_CLAW;
  if(/wood|bois/.test(t))return RECOR_FOOT_VISUALS.WOOD;
  if(/imperial/.test(t))return RECOR_FOOT_VISUALS.IMPERIAL;
  if(/lion/.test(t))return RECOR_FOOT_VISUALS.LION;
  if(/princess/.test(t))return RECOR_FOOT_VISUALS.PRINCESS;
  if(/carlton/.test(t))return RECOR_FOOT_VISUALS.CARLTON;
  if(/pedestal|socle/.test(t))return RECOR_FOOT_VISUALS.PEDESTAL;
  return "";
}
