const cloud={
  token:localStorage.getItem("hydropolis-auth-token")||"",
  user:null,
  currentProjectId:null,
  projects:[],
  dirty:false,
  loadingProject:false,
  persistentConfigured:false,
  started:false
};

function blankProjectState(){
  return {
    project:{name:"",client:"",location:"",date:"",intro:"",cover:""},
    rooms:[{id:"r1",title:"SDB MASTER",subtitle:"Robinetterie & sanitaires",manual:[]}],
    selected:[],
    commercial:{
      clientDiscount:0,vatRate:20,shippingFee:0,supplierShippingFee:0,
      supplierDiscounts:{"Amphora":50,"Catalano":64,"Coalbrook":50,"Zucchetti":55,"Lefroy Brooks":55,"Hotbath":50,"Recor":61.5385,"Ritmonio":55,"Nicolazzi":50,"Gessi":50}
    },
    showClientPrices:true,
    showSupplierReferences:true
  };
}
function stateStorageKey(){
  if(cloud.user?.id && cloud.currentProjectId)return `hydropolis-v21:${cloud.user.id}:${cloud.currentProjectId}`;
  return "hydropolis-v21";
}
function compactStateForCloud(){
  const raw={
    project:{...state.project},
    rooms:JSON.parse(JSON.stringify(state.rooms||[])),
    selected:(state.selected||[]).map(p=>{
      const q={...p};
      // blob: URLs point to local IndexedDB and cannot be used on another workstation.
      for(const k of ["image","pdfImage","technicalSheetUrl"]){
        if(typeof q[k]==="string" && q[k].startsWith("blob:"))q[k]="";
      }
      if(Array.isArray(q.images))q.images=q.images.filter(x=>typeof x==="string"&&!x.startsWith("blob:"));
      if(Array.isArray(q.pdfImages))q.pdfImages=q.pdfImages.filter(x=>typeof x==="string"&&!x.startsWith("blob:"));
      return q;
    }),
    commercial:JSON.parse(JSON.stringify(state.commercial||{})),
    showClientPrices:state.showClientPrices!==false,
    showSupplierReferences:state.showSupplierReferences!==false
  };
  return raw;
}
function applyProjectState(data){
  const fresh=blankProjectState();
  const src=(data && typeof data==="object")?data:{};
  state.project={...fresh.project,...(src.project||{})};
  state.rooms=Array.isArray(src.rooms)&&src.rooms.length?JSON.parse(JSON.stringify(src.rooms)):fresh.rooms;
  state.selected=Array.isArray(src.selected)?JSON.parse(JSON.stringify(src.selected)):[];
  state.commercial={...fresh.commercial,...(src.commercial||{})};
  state.showClientPrices=typeof src.showClientPrices==="boolean"?src.showClientPrices:true;
  state.showSupplierReferences=typeof src.showSupplierReferences==="boolean"?src.showSupplierReferences:true;
  loadState(src);
}
async function apiFetch(url,options={}){
  const headers={...(options.headers||{})};
  if(cloud.token)headers.Authorization=`Bearer ${cloud.token}`;
  if(options.body && !(options.body instanceof FormData) && !headers["Content-Type"])headers["Content-Type"]="application/json";
  const r=await fetch(url,{...options,headers});
  let data={};
  try{data=await r.json()}catch{}
  if(r.status===401 && !url.includes("/api/auth/")){
    cloudLogout(false);
    throw new Error("Session expirée");
  }
  if(!r.ok)throw new Error(data.error||data.detail||`Erreur ${r.status}`);
  return data;
}
function setAuthError(msg=""){
  const el=$("#authError");if(el)el.textContent=msg;
}
function showAuthMode(mode){
  $("#authOverlay").classList.remove("hidden");
  $("#setupForm").classList.toggle("hidden",mode!=="setup");
  $("#loginForm").classList.toggle("hidden",mode!=="login");
  setAuthError("");
}
function hideAuth(){
  $("#authOverlay").classList.add("hidden");
}
function updateUserBox(){
  const el=$("#userBox");if(!el)return;
  if(!cloud.user){el.innerHTML="";return}
  const contact=[cloud.user.title,cloud.user.phone,cloud.user.email].filter(Boolean).join(" · ");
  el.innerHTML=`<div class="user-box-main"><b>${esc(cloud.user.name)}</b><small>@${esc(cloud.user.username)}${cloud.user.role==="admin"?" · Admin":""}</small>${contact?`<small>${esc(contact)}</small>`:""}</div>
    <button class="tiny" id="logoutBtn">Déconnexion</button>`;
  $("#logoutBtn").onclick=()=>cloudLogout(true);
}
function updateCloudStatus(text=""){
  const el=$("#cloudProjectStatus");if(!el)return;
  if(text){el.textContent=text;return}
  const p=cloud.projects.find(x=>x.id===cloud.currentProjectId);
  if(!p){el.textContent="Aucun projet ouvert";return}
  el.textContent=`${p.name}${cloud.dirty?" · modifications non enregistrées":" · enregistré"}`;
}
function markCloudDirty(){
  if(cloud.loadingProject || !cloud.currentProjectId)return;
  cloud.dirty=true;
  updateCloudStatus();
}
function offlineUserKey(){return "hydropolis-offline-user"}
function offlineProjectListKey(){return cloud.user?.id?`hydropolis-project-list:${cloud.user.id}`:""}
function cloudLogout(reload=true){
  cloud.token="";cloud.user=null;cloud.currentProjectId=null;cloud.projects=[];
  localStorage.removeItem("hydropolis-auth-token");
  localStorage.removeItem("hydropolis-last-project");
  localStorage.removeItem(offlineUserKey());
  if(reload)location.reload();
  else showAuthMode("login");
}
async function checkAuth(){
  try{
    const status=await apiFetch("/api/auth/status");
    cloud.persistentConfigured=!!status.persistentConfigured;
    if(status.user){
      cloud.user=status.user;
      localStorage.setItem(offlineUserKey(),JSON.stringify(status.user));
      hideAuth();updateUserBox();
      return true;
    }
    showAuthMode(status.setupRequired?"setup":"login");
    return false;
  }catch(e){
    // Offline access is intentionally limited to a user that authenticated successfully before.
    // No password/session bypass is created: the cached profile only unlocks local browser drafts.
    if(!navigator.onLine && cloud.token){
      try{
        const cached=JSON.parse(localStorage.getItem(offlineUserKey())||"null");
        if(cached?.id){
          cloud.user=cached;
          cloud.persistentConfigured=true;
          hideAuth();updateUserBox();
          return true;
        }
      }catch{}
    }
    showAuthMode("login");setAuthError("Impossible de joindre le serveur : "+e.message);
    return false;
  }
}
async function loadCloudProjects(){
  const cacheKey=offlineProjectListKey();
  try{
    const data=await apiFetch("/api/projects");
    cloud.projects=data.projects||[];
    if(cacheKey)localStorage.setItem(cacheKey,JSON.stringify(cloud.projects));
  }catch(e){
    if(!navigator.onLine && cacheKey){
      try{cloud.projects=JSON.parse(localStorage.getItem(cacheKey)||"[]")||[]}catch{cloud.projects=[]}
      if(!cloud.projects.length)throw e;
    }else throw e;
  }
  renderProjectHub();
  updateCloudStatus(!navigator.onLine?"Mode hors connexion · projets du cache local":"");
  return cloud.projects;
}
async function openCloudProject(id){
  if(cloud.dirty && cloud.currentProjectId && cloud.currentProjectId!==id){
    if(!confirm("Le projet ouvert contient des modifications non enregistrées. Ouvrir un autre projet et abandonner ces changements ?"))return;
  }
  cloud.loadingProject=true;
  try{
    const draftKey=cloud.user?.id?`hydropolis-v21:${cloud.user.id}:${id}`:"";
    if(!navigator.onLine){
      let payload=null;
      try{payload=JSON.parse(localStorage.getItem(draftKey)||"null")}catch{}
      if(!payload)throw new Error("Ce projet n’est pas encore disponible dans le cache local. Ouvrez-le une fois avec une connexion avant de travailler hors ligne.");
      cloud.currentProjectId=id;
      localStorage.setItem("hydropolis-last-project",id);
      applyProjectState(payload);
      await hydrateCustomAssets();
      cloud.dirty=!!localStorage.getItem(`hydropolis-draft-at:${cloud.user.id}:${id}`);
      renderRoomSelect();bindProject();bindCommercial();renderSelection();renderRooms();renderCatalog();
      updateCloudStatus("Mode hors connexion · brouillon local");
      showView("project");
      return;
    }
    const data=await apiFetch(`/api/projects/${encodeURIComponent(id)}`);
    const draftAtKey=cloud.user?.id?`hydropolis-draft-at:${cloud.user.id}:${id}`:"";
    const draftAt=draftAtKey?Date.parse(localStorage.getItem(draftAtKey)||""):0;
    const serverAt=Date.parse(data.project.updatedAt||"")||0;
    let payload=data.project.data||{};
    let restoredDraft=false;
    if(draftKey&&draftAt>serverAt){
      try{
        const draft=JSON.parse(localStorage.getItem(draftKey)||"null");
        if(draft&&confirm("Un brouillon local plus récent que la version serveur existe pour ce projet. Le restaurer ?")){payload=draft;restoredDraft=true}
      }catch{}
    }
    cloud.currentProjectId=id;
    localStorage.setItem("hydropolis-last-project",id);
    applyProjectState(payload);
    saveState();
    await hydrateCustomAssets();
    cloud.dirty=restoredDraft;
    renderRoomSelect();bindProject();bindCommercial();renderSelection();renderRooms();renderCatalog();
    updateCloudStatus(restoredDraft?"Brouillon local restauré · à enregistrer":"");
    showView("project");
  }finally{cloud.loadingProject=false}
}
async function saveCloudProject(){
  if(!cloud.user)return;
  if(!navigator.onLine){
    if(!cloud.currentProjectId){toast("Créez ce projet une première fois en ligne avant de l’enregistrer hors connexion.");return}
    saveState();
    cloud.dirty=true;
    updateCloudStatus("Brouillon local · à synchroniser dès le retour en ligne");
    toast("Brouillon enregistré localement");
    return;
  }
  if(!cloud.currentProjectId){
    const created=await apiFetch("/api/projects",{
      method:"POST",
      body:JSON.stringify({name:state.project.name||"Nouveau projet",data:compactStateForCloud()})
    });
    cloud.currentProjectId=created.project.id;
    localStorage.setItem("hydropolis-last-project",cloud.currentProjectId);
  }else{
    await apiFetch(`/api/projects/${encodeURIComponent(cloud.currentProjectId)}`,{
      method:"PUT",
      body:JSON.stringify({name:state.project.name||"Projet",data:compactStateForCloud()})
    });
  }
  cloud.dirty=false;
  if(cloud.user?.id&&cloud.currentProjectId)localStorage.removeItem(`hydropolis-draft-at:${cloud.user.id}:${cloud.currentProjectId}`);
  await loadCloudProjects();
  updateCloudStatus("Projet enregistré ✓");
  setTimeout(()=>updateCloudStatus(),1200);
}
async function createCloudProject(){
  const name=prompt("Nom du nouveau projet","Nouveau projet");
  if(!name)return;
  const data=blankProjectState();
  data.project.name=name.trim();
  const created=await apiFetch("/api/projects",{method:"POST",body:JSON.stringify({name,data})});
  await loadCloudProjects();
  await openCloudProject(created.project.id);
}
async function duplicateCloudProject(id){
  const source=cloud.projects.find(p=>p.id===id);
  const name=prompt("Nom de la copie",`${source?.name||"Projet"} — copie`);
  if(!name)return;
  await apiFetch(`/api/projects/${encodeURIComponent(id)}/duplicate`,{
    method:"POST",body:JSON.stringify({name})
  });
  await loadCloudProjects();
}
async function deleteCloudProject(id){
  const p=cloud.projects.find(x=>x.id===id);
  if(!confirm(`Supprimer définitivement « ${p?.name||"ce projet"} » ?`))return;
  await apiFetch(`/api/projects/${encodeURIComponent(id)}`,{method:"DELETE"});
  if(cloud.currentProjectId===id){
    cloud.currentProjectId=null;
    localStorage.removeItem("hydropolis-last-project");
    applyProjectState(blankProjectState());
    cloud.dirty=false;
  }
  await loadCloudProjects();
}
async function importLegacyLocalProject(){
  let legacy=null;
  try{legacy=JSON.parse(localStorage.getItem("hydropolis-v21")||"null")}catch{}
  if(!legacy)return alert("Aucun ancien projet local à importer sur cet ordinateur.");
  const name=legacy?.project?.name||"Projet local importé";
  const created=await apiFetch("/api/projects",{
    method:"POST",body:JSON.stringify({name,data:legacy})
  });
  await loadCloudProjects();
  await openCloudProject(created.project.id);
}
function formatProjectDate(s){
  if(!s)return "";
  try{return new Intl.DateTimeFormat("fr-FR",{dateStyle:"short",timeStyle:"short"}).format(new Date(s))}catch{return s}
}


function technicalSheetHref(p){
  if(p?.customTechnicalSheet && p?.technicalSheetAsset?.file && cloud.currentProjectId && cloud.token){
    return `${location.origin}/api/project-assets/${encodeURIComponent(cloud.currentProjectId)}/${encodeURIComponent(p.technicalSheetAsset.file)}?access=${encodeURIComponent(cloud.token)}`;
  }
  return p?.technicalSheetUrl||"";
}
function technicalSheetIsPdf(p){
  const url=technicalSheetHref(p);
  const ritmonioOfficial=/^Ritmonio$/i.test(String(p?.manufacturer||"")) && /ritmonio\.it\/[^\s]*\/download\/\?code=/i.test(url);
  return p?.technicalSheetType==="pdf" || !!p?.technicalSheetAsset?.file || /\.pdf(?:\?|$)/i.test(url) || ritmonioOfficial;
}
function fileToBase64(file){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=()=>{
      const raw=String(reader.result||"");
      resolve(raw.includes(",")?raw.split(",").pop():raw);
    };
    reader.onerror=()=>reject(reader.error||new Error("Lecture du fichier impossible"));
    reader.readAsDataURL(file);
  });
}
async function uploadTechnicalSheet(p,file){
  if(!file)return;
  if(file.type!=="application/pdf" && !/\.pdf$/i.test(file.name||"")){
    throw new Error("Choisissez une fiche technique au format PDF.");
  }
  if(file.size>10*1024*1024)throw new Error("Le PDF doit faire moins de 10 Mo.");

  if(!cloud.currentProjectId){
    await saveCloudProject();
  }

  const dataBase64=await fileToBase64(file);
  const payload=await apiFetch(`/api/projects/${encodeURIComponent(cloud.currentProjectId)}/assets/${encodeURIComponent(p.id)}/technical-sheet`,{
    method:"POST",
    body:JSON.stringify({
      fileName:file.name,
      mime:"application/pdf",
      dataBase64,
      previousFile:p.technicalSheetAsset?.file||""
    })
  });

  p.technicalSheetAsset=payload.asset;
  p.technicalSheetUrl="";
  p.technicalSheetLabel=file.name||"Fiche technique personnalisée";
  p.technicalSheetType="pdf";
  p.customTechnicalSheet=true;
  p.includeTechnicalSheet=false;

  saveState();
  await saveCloudProject();
}
async function deleteCustomTechnicalSheet(p){
  if(p?.technicalSheetAsset?.file && cloud.currentProjectId){
    try{
      await apiFetch(`/api/projects/${encodeURIComponent(cloud.currentProjectId)}/assets/${encodeURIComponent(p.technicalSheetAsset.file)}`,{method:"DELETE"});
    }catch(e){console.warn("[delete technical sheet]",e)}
  }
  delete p.technicalSheetAsset;
}

