async function lookupCatalogPhoto(reference,button){
  const p=CATALOG.find(x=>x.reference===reference);
  if(!p)return;
  const card=button.closest(".result");
  const thumb=$(".catalog-thumb",card);
  const info=$(".photo-status",card);
  button.disabled=true;
  button.textContent="Recherche Sanitairkamer…";
  if(info)info.textContent="Recherche Sanitairkamer par référence produit…";

  try{
    let img=await fetchManufacturerImage(p,true,{imageOnly:true});

    // Hotbath order:
    // 1. official exact; 2. web exact; 3. official generic; 4. web generic.
    // The server already handles Hotbath fallbacks; do not repeat the search.
    if(img?.src){
      thumb.innerHTML=`<img src="${img.src}" alt="${p.reference}" class="catalog-live-image">`;
      const rendered=$(".catalog-live-image",thumb);
      if(rendered){
        rendered.onerror=()=>{
          thumb.innerHTML=`<div class="photo-missing"><b>Photo indisponible</b><br>${p.finish||""}</div>`;
          if(info)info.textContent="Le visuel distant est indisponible. Aucune image cassée n'est conservée.";
        };
      }
      if(info)info.innerHTML=`<b>${imageBadge(img,p)}</b>${img.note?`<br>${img.note}`:""}`;
      button.textContent="Actualiser la photo";
    }else{
      thumb.innerHTML=`<div class="photo-missing"><b>Photo fabricant</b><br>${p.finish||""}<br>indisponible</div>`;
      if(info)info.innerHTML=`Aucun visuel exploitable trouvé.${img?.note?`<br>${img.note}`:""}${img?.technicalSheetUrl?`<br><b>Fiche technique disponible.</b>`:""}`;
      button.textContent="Réessayer";
    }
    renderCatalog();
  }catch(e){
    if(info)info.textContent="Aucune photo exploitable : "+e.message;
    button.textContent="Réessayer";
  }finally{
    button.disabled=false;
  }
}

async function enrichSelectedPhoto(id,force=false){
  const p=state.selected.find(x=>x.id===id);
  if(!p)return;
  p.imageStatus="Recherche du meilleur visuel…";
  renderRooms();

  try{
    let img=await fetchManufacturerImage(p,force);

    // The server already handles Hotbath fallbacks; do not repeat the search.
    if(img.src){
      p.image=img.src;
      p.images=img.images||[img.src].filter(Boolean);
      p.pdfImage=img.src;
      p.pdfImages=/catalano/i.test(p.manufacturer||"")?p.images.slice():(/recor/i.test(p.manufacturer||"")?p.images.slice(0,4):p.images.slice(0,2));
      p.remoteImageUrl=img.remoteUrl||"";
      p.remoteImages=img.remoteImages||[];
      p.imageSource=img.source;
      p.imageFinishMatch=img.finishMatch;
      p.imageStatus=imageBadge(img,p);
      p.imageSimulation=false;
      p.customImage=false;
      if(/recor/i.test(p.manufacturer||"") && p.category==="Bain")p.recorImageQualityVersion=2;
      if(/nicolazzi/i.test(p.manufacturer||""))p.nicolazziVisualVersion=2;
    }else if(!p.image){
      p.imageStatus="Photo fabricant indisponible";
    }

    p.imageNote=img.note;
    p.resolvedManufacturerUrl=img.resolvedManufacturerUrl||p.resolvedManufacturerUrl||p.manufacturerUrl||"";
    p.drawingUrl=img.drawingUrl||p.drawingUrl||"";
    p.drawingType=img.drawingType||p.drawingType||"";
    p.drawingLabel=img.drawingLabel||p.drawingLabel||"";
    p.drawingPage=Number(img.drawingPage||p.drawingPage||1);
    p.cadDrawingUrl=img.cadDrawingUrl||p.cadDrawingUrl||"";
    p.cadDrawingLabel=img.cadDrawingLabel||p.cadDrawingLabel||"";
    p.cadDrawingType=img.cadDrawingType||p.cadDrawingType||"";
    p.technicalSheetUrl=img.technicalSheetUrl||p.technicalSheetUrl||"";
    p.technicalSheetLabel=img.technicalSheetLabel||p.technicalSheetLabel||"Fiche technique";
    p.technicalSheetType=img.technicalSheetType||p.technicalSheetType||"";
    p.technicalSheetPage=Number(img.technicalSheetPage||p.technicalSheetPage||1);
    p.installationGuideUrl=img.installationGuideUrl||p.installationGuideUrl||"";
    p.installationGuideLabel=img.installationGuideLabel||p.installationGuideLabel||"Notice d'installation";
    if(/nicolazzi/i.test(p.manufacturer||"")){
      p.nicolazziHandleOptions=img.handleOptions||p.nicolazziHandleOptions||[];
      p.nicolazziFinishOptions=img.finishOptions||p.nicolazziFinishOptions||[];
      p.commercialSource=img.commercialSource||p.commercialSource||"";
      p.commercialSourceUrl=img.commercialSourceUrl||p.commercialSourceUrl||"";
      p.nicolazziVisualVersion=2;
    }
    if(/catalano/i.test(p.manufacturer||"")){
      p.catalanoGalleryComplete=img.galleryComplete===true;
      p.catalanoGallerySource=img.gallerySource||"catalano-official-product-page";
    }
  }catch(e){
    p.imageStatus=p.image?"Photo existante conservée":"Photo fabricant non trouvée";
    p.imageNote=e.message;
  }

  saveState();
  renderRooms();
  renderSelection();
}

function loadState(override=null){
  const fresh=blankProjectState();
  state.project={...fresh.project};
  state.rooms=JSON.parse(JSON.stringify(fresh.rooms));
  state.selected=[];
  state.commercial=JSON.parse(JSON.stringify(fresh.commercial));
  state.showClientPrices=true;
  state.showSupplierReferences=true;

  try{
    let s=override;
    if(!s){
      const raw=localStorage.getItem(stateStorageKey());
      s=raw?JSON.parse(raw):null;
    }
    if(s && typeof s==="object"){
      state.project={...fresh.project,...(s.project||{})};
      state.rooms=Array.isArray(s.rooms)&&s.rooms.length?JSON.parse(JSON.stringify(s.rooms)):fresh.rooms;
      state.selected=Array.isArray(s.selected)?JSON.parse(JSON.stringify(s.selected)):[];
      state.commercial={...fresh.commercial,...(s.commercial||{})};
      state.showClientPrices=typeof s.showClientPrices==="boolean"?s.showClientPrices:true;
      state.showSupplierReferences=typeof s.showSupplierReferences==="boolean"?s.showSupplierReferences:true;
    }
  }catch(e){console.warn("[loadState]",e);}

  if(!state.rooms?.length)state.rooms=[{id:"r1",title:"SDB MASTER",subtitle:"",manual:[]}];
  state.rooms=state.rooms.map((r,i)=>({
    ...r,
    id:r.id||`r${i+1}`,
    manual:(Array.isArray(r.manual)?r.manual:[])
      .filter(m=>m && String(m.label||"").trim())
      .map(m=>({...m,label:String(m.label||"").trim(),price:Math.max(0,Number(m.price)||0)}))
  }));
  state.selected=(state.selected||[]).filter(Boolean).map(p=>({...p,roomId:p.roomId||state.rooms[0].id}));

  if(typeof state.showClientPrices!=="boolean")state.showClientPrices=true;
  if(typeof state.showSupplierReferences!=="boolean")state.showSupplierReferences=true;

  if(!state.commercial || typeof state.commercial!=="object")state.commercial=fresh.commercial;
  if(!state.commercial.supplierDiscounts || typeof state.commercial.supplierDiscounts!=="object")state.commercial.supplierDiscounts={};
  const defaultSupplierDiscounts={"Amphora":50,"Catalano":64,"Coalbrook":50,"Zucchetti":55,"Lefroy Brooks":55,"Hotbath":50,"Recor":61.5385,"Ritmonio":55,"Nicolazzi":50,"Gessi":50};
  Object.entries(defaultSupplierDiscounts).forEach(([maker,rate])=>{
    if(state.commercial.supplierDiscounts[maker]===undefined || state.commercial.supplierDiscounts[maker]===null || state.commercial.supplierDiscounts[maker]==="")state.commercial.supplierDiscounts[maker]=rate;
  });
  // V11.23 commercial-condition migration: Lefroy Brooks moved from the former
  // default 50% to the current negotiated 55%. Preserve any non-default manual
  // condition a user may already have entered.
  if(!state.commercial.supplierDiscountMigrationV1123){
    const legacyLefroy=Number(state.commercial.supplierDiscounts["Lefroy Brooks"]);
    if(!Number.isFinite(legacyLefroy) || Math.abs(legacyLefroy-50)<0.0001)state.commercial.supplierDiscounts["Lefroy Brooks"]=55;
    if(state.commercial.supplierDiscounts.Ritmonio===undefined || state.commercial.supplierDiscounts.Ritmonio===null || state.commercial.supplierDiscounts.Ritmonio==="")state.commercial.supplierDiscounts.Ritmonio=55;
    state.commercial.supplierDiscountMigrationV1123=true;
  }

  state.commercial.clientDiscount=Math.max(0,Math.min(100,Number(state.commercial.clientDiscount)||0));
  state.commercial.vatRate=Math.max(0,Math.min(100,state.commercial.vatRate===null||state.commercial.vatRate===undefined||state.commercial.vatRate===""?20:Number(state.commercial.vatRate)));
  state.commercial.shippingFee=Math.max(0,Number(state.commercial.shippingFee)||0);
  state.commercial.supplierShippingFee=Math.max(0,Number(state.commercial.supplierShippingFee)||0);
  // V11.21 migration: if an older project manually copied exactly the Recor carriage
  // into Port fournisseur, absorb it into the new automatic Recor shipping layer once.
  if(!state.commercial.recorFreightMovedV1120){
    const legacyAuto=(state.selected||[]).filter(p=>p?.manufacturer==="Recor").reduce((sum,p)=>sum+Math.max(0,Number(p?.mandatoryFreight)||0),0);
    if(legacyAuto>0 && Math.abs(state.commercial.supplierShippingFee-legacyAuto)<0.01)state.commercial.supplierShippingFee=0;
    state.commercial.recorFreightMovedV1120=true;
  }

  state.selected.forEach(p=>{
    if(p.clientDiscountOverride!==undefined && p.clientDiscountOverride!==null && p.clientDiscountOverride!==""){
      p.clientDiscountOverride=Math.max(0,Math.min(100,Number(p.clientDiscountOverride)||0));
    }else delete p.clientDiscountOverride;
    if(typeof p.leadTime!=="string")p.leadTime="";
    if(p.catalogTotalPrice===undefined || p.catalogTotalPrice===null)p.catalogTotalPrice=Number(p.totalPrice||0);
    if(p.catalogPrice===undefined || p.catalogPrice===null)p.catalogPrice=Number(p.price||0);
    if(typeof p.customTechnicalSheet!=="boolean")p.customTechnicalSheet=false;
  });

  // V11: never delete a free line solely because its label/price resembles a catalogue product.
  manualCleanupPending=false;
}
function saveState(){
  const compact={
    ...state,
    selected:(state.selected||[]).map(p=>{
      const q={...p};
      if(!q.customImage){
        if(typeof q.image==="string" && /^data:/i.test(q.image)) q.image="";
        if(Array.isArray(q.images)) q.images=q.images.filter(x=>typeof x==="string" && !/^data:/i.test(x));
        if(typeof q.pdfImage==="string" && /^data:/i.test(q.pdfImage)) q.pdfImage=q.image||"";
        if(Array.isArray(q.pdfImages)) q.pdfImages=q.pdfImages.filter(x=>typeof x==="string" && !/^data:/i.test(x));
      }
      return q;
    })
  };
  const payload=JSON.stringify(compact);
  try{
    localStorage.setItem(stateStorageKey(),payload);
    if(!cloud.loadingProject&&cloud.user?.id&&cloud.currentProjectId)localStorage.setItem(`hydropolis-draft-at:${cloud.user.id}:${cloud.currentProjectId}`,new Date().toISOString());
    markCloudDirty();
    try{renderV11Overview()}catch{}
    return true;
  }catch(e){
    console.warn("[Hydropolis storage] quota dépassé",e);
    try{
      Object.keys(localStorage).forEach(k=>{
        if(/^hydropolis-manufacturer-/i.test(k))localStorage.removeItem(k);
      });
      localStorage.setItem(stateStorageKey(),payload);
      return true;
    }catch(e2){
      console.warn("[Hydropolis storage] projet conservé en mémoire",e2);
      return false;
    }
  }
}
function unique(k){return [...new Set(CATALOG.map(x=>x[k]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"fr"));}
function fillSelect(id,values,keepValue=true){
 const el=$("#"+id); if(!el)return;
 const previous=keepValue?el.value:"";
 const first=el.querySelector("option");
 const placeholder=first?first.cloneNode(true):new Option("Toutes","");
 el.innerHTML=""; el.appendChild(placeholder); placeholder.value="";
 values.filter(Boolean).sort((a,b)=>String(a).localeCompare(String(b),"fr",{sensitivity:"base"})).forEach(v=>{
   const o=document.createElement("option");o.value=v;o.textContent=v;el.appendChild(o);
 });
 if(previous && values.includes(previous)) el.value=previous; else el.value="";
}
function valuesFor(key,manufacturer=""){
 return [...new Set(CATALOG.filter(p=>!manufacturer||p.manufacturer===manufacturer).map(p=>p[key]).filter(Boolean))];
}
function catalogueRowsForFilters({manufacturer="",collection="",category=""}={}){
  return CATALOG.filter(p=>{
    // This manufacturer test is the non-negotiable first scope for every brand.
    if(manufacturer && p.manufacturer!==manufacturer)return false;
    if(collection && p.collection!==collection)return false;
    if(category && p.category!==category)return false;
    return true;
  });
}
function filterValues(key,scope={}){
  return [...new Set(
    catalogueRowsForFilters(scope).map(p=>p?.[key]).filter(Boolean)
  )].sort((a,b)=>String(a).localeCompare(String(b),"fr",{sensitivity:"base"}));
}
function updateDependentFilters(resetCollection=false,resetCategory=false,resetFinish=false){
  const manufacturer=$("#manufacturerFilter")?.value||"";

  // COLLECTIONS: only those belonging to the selected manufacturer.
  fillSelect(
    "collectionFilter",
    filterValues("collection",{manufacturer}),
    !resetCollection
  );

  const collection=$("#collectionFilter")?.value||"";

  // CATEGORIES: manufacturer first, then current collection if selected.
  fillSelect(
    "categoryFilter",
    filterValues("category",{manufacturer,collection}),
    !resetCategory
  );

  const category=$("#categoryFilter")?.value||"";

  // FINISHES: always manufacturer-scoped. Collection/category narrow it further,
  // but a finish from another manufacturer can never appear.
  fillSelect(
    "finishFilter",
    filterValues("finish",{manufacturer,collection,category}),
    !resetFinish
  );

  // Guard against a stale browser value after progressive catalogue loading.
  const validCollection=new Set(filterValues("collection",{manufacturer}));
  if($("#collectionFilter")?.value && !validCollection.has($("#collectionFilter").value)){
    $("#collectionFilter").value="";
  }
  const currentCollection=$("#collectionFilter")?.value||"";
  const validCategory=new Set(filterValues("category",{manufacturer,collection:currentCollection}));
  if($("#categoryFilter")?.value && !validCategory.has($("#categoryFilter").value)){
    $("#categoryFilter").value="";
  }
  const currentCategory=$("#categoryFilter")?.value||"";
  const validFinish=new Set(filterValues("finish",{manufacturer,collection:currentCollection,category:currentCategory}));
  if($("#finishFilter")?.value && !validFinish.has($("#finishFilter").value)){
    $("#finishFilter").value="";
  }
}

