function initPreviewParallax(){
  const host=document.querySelector(".preview-bg");
  if(!host || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  if(host._parallaxHandler) host.removeEventListener("scroll",host._parallaxHandler);

  let raf=0;
  const update=()=>{
    raf=0;
    const hostRect=host.getBoundingClientRect();
    host.querySelectorAll("[data-parallax-page]").forEach(page=>{
      const rect=page.getBoundingClientRect();
      const center=(rect.top+rect.bottom)/2;
      const viewportCenter=(hostRect.top+hostRect.bottom)/2;
      const delta=Math.max(-1,Math.min(1,(center-viewportCenter)/Math.max(hostRect.height,1)));
      page.style.setProperty("--parallax-progress",delta.toFixed(3));
      page.querySelectorAll("[data-parallax-layer]").forEach(layer=>{
        const strength=parseFloat(layer.dataset.parallaxLayer||"0");
        const y=delta*strength*140;
        layer.style.setProperty("--parallax-y",`${y.toFixed(2)}px`);
      });
    });
  };
  const handler=()=>{
    if(!raf) raf=requestAnimationFrame(update);
  };
  host._parallaxHandler=handler;
  host.addEventListener("scroll",handler,{passive:true});
  window.addEventListener("resize",handler,{passive:true});
  update();
}


async function waitForDocumentImages(timeoutMs=5000){
  const imgs=[...document.querySelectorAll("#document img")];
  if(!imgs.length)return;
  await Promise.race([
    Promise.all(imgs.map(img=>{
      if(img.complete)return Promise.resolve();
      return new Promise(resolve=>{
        img.addEventListener("load",resolve,{once:true});
        img.addEventListener("error",resolve,{once:true});
      });
    })),
    new Promise(resolve=>setTimeout(resolve,timeoutMs))
  ]);
}
async function exportClientPdf(){
  if(!validateRecorFeet(true)){
    showView("project");
    return;
  }

  // The document is rebuilt immediately before export so the PDF always
  // reflects the latest project data.
  showView("preview");
  buildDocument();

  const btns=[$("#printBtn"),$("#exportPdfTopBtn")].filter(Boolean);
  btns.forEach(b=>{b.disabled=true;b.dataset.oldText=b.textContent;b.textContent="Préparation du PDF…";});

  const oldTitle=document.title;
  const safeName=String(state.project?.name||"Dossier client Hydropolis")
    .replace(/[\\/:*?"<>|]+/g," ")
    .replace(/\s+/g," ")
    .trim();
  document.title=`${safeName} - Hydropolis`;

  try{
    if(document.fonts?.ready)await Promise.race([document.fonts.ready,new Promise(r=>setTimeout(r,1500))]);
    await waitForDocumentImages(6000);

    document.body.classList.add("pdf-exporting");
    await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
    window.print();
  }finally{
    // afterprint is not consistently synchronous across browsers.
    const restore=()=>{
      document.body.classList.remove("pdf-exporting");
      document.title=oldTitle;
      btns.forEach(b=>{b.disabled=false;b.textContent=b.dataset.oldText||"Exporter PDF";});
      window.removeEventListener("afterprint",restore);
    };
    window.addEventListener("afterprint",restore,{once:true});
    setTimeout(()=>{
      if(document.body.classList.contains("pdf-exporting"))restore();
    },10000);
  }
}

