async function loadSupplierCatalogs(){
  const countEl=$("#resultCount");
  const catalogCount=$("#catalogCount");

  let manifest;
  try{
    const mr=await fetch("/catalog_manifest.json",{cache:"no-cache"});
    if(!mr.ok)throw new Error("manifest HTTP "+mr.status);
    manifest=await mr.json();
  }catch(e){
    console.error("[catalog manifest]",e);
    if(countEl)countEl.textContent=`${CATALOG.length} références · catalogues externes indisponibles`;
    return 0;
  }

  let loaded=0, failed=0;
  const known=new Set(CATALOG.map(p=>`${p.manufacturer||""}|${p.reference||""}`));

  const loadChunk=async(chunk)=>{
    try{
      const r=await fetch("/"+chunk.file,{cache:"force-cache"});
      if(!r.ok)throw new Error(`HTTP ${r.status}`);
      let rows;
      if(/\.gz$/i.test(String(chunk.file||""))){
        if(typeof DecompressionStream!=="function")throw new Error("Navigateur sans prise en charge gzip catalogue");
        const stream=r.body.pipeThrough(new DecompressionStream("gzip"));
        rows=JSON.parse(await new Response(stream).text());
      }else{
        rows=await r.json();
      }
      if(Array.isArray(rows)){
        for(const p of rows){
          const key=`${p?.manufacturer||""}|${p?.reference||""}`;
          if(!known.has(key)){
            known.add(key);CATALOG.push(p);loaded++;
          }
        }
      }
      harmonizeSavedCatalogProducts();
      refreshCatalogUiAfterChunk();
      renderSelection();
      renderRooms();
      return true;
    }catch(e){
      failed++;
      console.error(`[catalog chunk] ${chunk.file}`,e);
      return false;
    }
  };

  const chunks=manifest.chunks||[];
  const priority=chunks.filter(c=>!/^Zucchetti/i.test(c.label||""));
  const zucchetti=chunks.filter(c=>/^Zucchetti/i.test(c.label||""));

  if(countEl)countEl.textContent=`${CATALOG.length} références · chargement Coalbrook, Catalano, Hotbath, Lefroy Brooks, Recor, Ritmonio, Nicolazzi et Gessi…`;
  await Promise.allSettled(priority.map(loadChunk));

  for(let i=0;i<zucchetti.length;i+=3){
    const batch=zucchetti.slice(i,i+3);
    if(countEl)countEl.textContent=`${CATALOG.length} références · chargement Zucchetti ${i+1}-${Math.min(i+3,zucchetti.length)}/${zucchetti.length}…`;
    await Promise.allSettled(batch.map(loadChunk));
    await new Promise(resolve=>setTimeout(resolve,0));
  }

  harmonizeSavedCatalogProducts();
  refreshCatalogUiAfterChunk();
  renderSelection();
  renderRooms();

  if(countEl){
    countEl.textContent=failed
      ?`${CATALOG.length} références disponibles · ${failed} fichier(s) non chargé(s)`
      :`${CATALOG.length} références disponibles`;
  }
  updateCatalogSidebar();
  renderDashboardEcosystem();
  return loaded;
}
function harmonizeSavedCatalogProducts(){
  const byKey=new Map(CATALOG.map(p=>[`${p.manufacturer||""}|${p.reference||""}`,p]));
  const byRef=new Map(CATALOG.map(p=>[p.reference,p]));

  for(const p of state.selected||[]){
    const c=byKey.get(`${p.manufacturer||""}|${p.reference||""}`)||byRef.get(p.reference);
    if(!c)continue;

    const runtime={
      id:p.id,roomId:p.roomId,accessoryFor:p.accessoryFor,
      image:p.image,images:p.images,pdfImage:p.pdfImage,pdfImages:p.pdfImages,
      remoteImageUrl:p.remoteImageUrl,remoteImages:p.remoteImages,
      imageSource:p.imageSource,imageFinishMatch:p.imageFinishMatch,imageStatus:p.imageStatus,imageNote:p.imageNote,
      resolvedManufacturerUrl:p.resolvedManufacturerUrl,
      drawingUrl:p.drawingUrl,drawingType:p.drawingType,drawingLabel:p.drawingLabel,drawingPage:p.drawingPage,
      cadDrawingUrl:p.cadDrawingUrl,cadDrawingLabel:p.cadDrawingLabel,cadDrawingType:p.cadDrawingType,
      technicalSheetUrl:p.technicalSheetUrl,technicalSheetLabel:p.technicalSheetLabel,technicalSheetPage:p.technicalSheetPage,
      installationGuideUrl:p.installationGuideUrl,installationGuideLabel:p.installationGuideLabel,
      includeDrawing:p.includeDrawing,includeTechnicalSheet:p.includeTechnicalSheet,includeInstallationGuide:p.includeInstallationGuide,
      customImage:p.customImage,imageSimulation:p.imageSimulation,imageSource:p.imageSource,imageFinishMatch:p.imageFinishMatch,imageNote:p.imageNote,remoteImageUrl:p.remoteImageUrl,remoteImages:p.remoteImages,webImageSourcePage:p.webImageSourcePage,clientDiscountOverride:p.clientDiscountOverride,leadTime:p.leadTime,priceOverride:p.priceOverride,originalDesignation:p.originalDesignation,catalogPrice:p.catalogPrice,catalogTotalPrice:p.catalogTotalPrice,customTechnicalSheet:p.customTechnicalSheet,technicalSheetAsset:p.technicalSheetAsset,catalanoGalleryComplete:p.catalanoGalleryComplete,catalanoGallerySource:p.catalanoGallerySource,recorImageQualityVersion:p.recorImageQualityVersion,
      nicolazziVisualVersion:p.nicolazziVisualVersion,nicolazziHandleOptions:p.nicolazziHandleOptions,nicolazziFinishOptions:p.nicolazziFinishOptions,commercialSource:p.commercialSource,commercialSourceUrl:p.commercialSourceUrl
    };

    Object.assign(p,c,runtime);
  }
}
